def semver_sort(versions):
    def parse_version(version):
        # Split by '+' to remove build metadata
        version_without_build = version.split('+')[0]

        # Split by '-' to separate base version and pre-release
        if '-' in version_without_build:
            parts = version_without_build.split('-', 1)
            base = parts[0]
            prerelease = parts[1]
        else:
            base = version_without_build
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        base_parts = base.split('.')
        major = int(base_parts[0])
        minor = int(base_parts[1]) if len(base_parts) > 1 else 0
        patch = int(base_parts[2]) if len(base_parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            prerelease_identifiers = prerelease.split('.')
            # Convert identifiers: all-digit ones to int with a marker, others stay as strings
            parsed_prerelease = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    parsed_prerelease.append((0, int(identifier)))  # 0 marker for numeric
                else:
                    parsed_prerelease.append((1, identifier))  # 1 marker for string
        else:
            parsed_prerelease = None

        return (major, minor, patch, prerelease_identifiers if prerelease else [], parsed_prerelease is not None)

    def compare_key(item):
        version, index = item
        parsed = parse_version(version)
        major, minor, patch, prerelease_ids, has_prerelease = parsed

        # Sort key: (major, minor, patch, has_prerelease_inverted, prerelease_parsed, original_index)
        # has_prerelease_inverted: False (0) for with prerelease (sorts first), True (1) for without (sorts second)
        # This is inverted because False < True
        if has_prerelease:
            prerelease_parsed = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    prerelease_parsed.append((0, int(identifier)))
                else:
                    prerelease_parsed.append((1, identifier))
        else:
            prerelease_parsed = None

        return (major, minor, patch, has_prerelease, prerelease_parsed if prerelease_parsed else [], index)

    # Add indices to maintain stable sort for equal precedence
    indexed_versions = [(v, i) for i, v in enumerate(versions)]

    # Sort with custom key
    sorted_versions = sorted(indexed_versions, key=compare_key)

    # Extract just the version strings
    return [v for v, _ in sorted_versions]

